solution.javascript:
function findKthLargest(nums, k) {
  k = nums.length - k;
  function quickSelect(l, r) {
    const pivot = nums[r]; let p = l;
    for (let i = l; i < r; i++) if (nums[i] <= pivot) [nums[p], nums[i]] = [nums[i], nums[p++]];
    [nums[p], nums[r]] = [nums[r], nums[p]];
    if (p > k) return quickSelect(l, p - 1);
    if (p < k) return quickSelect(p + 1, r);
    return nums[p];
  }
  return quickSelect(0, nums.length - 1);
}

solution.cpp:
int findKthLargest(vector<int>& nums, int k) {
    k = nums.size() - k;
    function<int(int,int)> qs = [&](int l, int r) {
        int pivot = nums[r], p = l;
        for (int i = l; i < r; i++) if (nums[i] <= pivot) swap(nums[p++], nums[i]);
        swap(nums[p], nums[r]);
        if (p > k) return qs(l, p - 1);
        if (p < k) return qs(p + 1, r);
        return nums[p];
    };
    return qs(0, nums.size() - 1);
}
